def structure():
    bundles = []
    n = 0
    for bid, bname, bdesc, rationale, brefs, layers in STRUCTURE:
        layer_rows = []
        for lid, lname, ldesc, lrefs, findings in layers:
            finding_rows = []
            for fid, fname, fdesc, primary_kind, frefs, value_kind, required, serial in findings:
                k2 = QUESTION_KINDS[(n + 8) % len(QUESTION_KINDS)]
                k3 = QUESTION_KINDS[(n + 18) % len(QUESTION_KINDS)]
                n += 1
                questions = [
                    {"id": f"{fid}-q01", "text": f"What governed logistics assertion is recorded for {fname.lower()}, for which movement, consignment, cargo scope, leg, location, time and revision?", "kind": primary_kind, "answer_data": [fname, "movement, cargo and leg scope", "location, time, state and revision"]},
                    {"id": f"{fid}-q02", "text": f"Which source, actor, authority, observation or method establishes {fname.lower()}, with what evidence, confidence, freshness and limitations?", "kind": k2, "answer_data": ["source, actor and authority", "observation or method and evidence", "confidence, freshness and limitations"]},
                    {"id": f"{fid}-q03", "text": f"Which validation, access, transition or correction rule governs {fname.lower()}, and how are predecessors, successors and external master bindings preserved?", "kind": k3, "answer_data": ["validation and access rule", "authorized transition and effective time", "predecessor, successor and external reference"]},
                ]
                data_elements = [{"id": f"{fid}-data", "name": f"{fname} assertion", "description": f"Structured goods-movement answer data for {fname.lower()}, including object scope, place, time, state, source and provenance.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": frefs}]
                artifacts = [{"id": f"{fid}-artifact", "name": f"{fname} record", "description": f"Versioned logistics record supporting {fname.lower()} with evidence, provenance and access marking.", "media_or_form": ["structured movement assertion", "event or decision statement", "resolvable evidence or master-system index"], "serial": serial, "identity_strategy": "Authoritative logistics master-system identifier first; otherwise a Dimension-governed UUID or ULID.", "source_refs": frefs}]
                finding_rows.append({"id": fid, "name": fname, "description": fdesc, "source_refs": frefs, "questions": questions, "data_elements": data_elements, "artifacts": artifacts, "inline_only_rationale": None})
            layer_rows.append({"id": lid, "name": lname, "description": ldesc, "source_refs": lrefs, "findings": finding_rows})
        bundles.append({"id": bid, "name": bname, "description": bdesc, "rationale": rationale, "source_refs": brefs, "layers": layer_rows})
    return {"bundles": bundles}


